-- antiguidade_biblia_ficcao.sql
-- Semente Canônica Dedicada do Lote 12: Antiguidade, Tradição Bíblica & Genealogias Ficcionais.
-- Contempla 19 árvores genealógicas (438 membros no acervo):
-- 1. 18ª Dinastia do Egito (Tutmésides e Amarna)
-- 2. 19ª Dinastia do Egito (Ramsésidas)
-- 3. Dinastias 21 a 23 do Egito (Terceiro Período Intermediário)
-- 4. Linhagem de Confúcio (Família Kong)
-- 5. Família Lurie / Luria
-- 6. Casa Real de Davi (Linhagem Bíblica)
-- 7. Genealogia de Adão (Gênesis / Antediluviana)
-- 8. Genealogia de Jesus (Lucas — Linhagem por Natã e Parentesco)
-- 9. Genealogia de Jesus (Mateus — Linhagem Régia)
-- 10. Linhagem de Moisés e Aarão (Tribo de Levi)
-- 11. Patriarcas de Israel (Abraão a José)
-- 12. Família Buendía (Cem Anos de Solidão)
-- 13. Família Compson (O Som e a Fúria)
-- 14. Família Corleone (O Poderoso Chefão)
-- 15. Família Karamazov (Dostoiévski)
-- 16. Casa Lannister (As Crônicas de Gelo e Fogo)
-- 17. Linhagem Skywalker (Star Wars)
-- 18. Casa Targaryen (As Crônicas de Gelo e Fogo)
-- 19. Família Terra Cambará (O Tempo e o Vento)

-- =====================================================================
-- 0. ATUALIZAÇÃO DO TIPO DE TEMPO PARA ÁRVORES E MEMBROS FICCIONAIS
-- =====================================================================
UPDATE arvores SET tipo_tempo = 'ficticio' WHERE id IN ('pub_arv_buendia', 'pub_arv_compson', 'pub_arv_corleone', 'pub_arv_karamazov', 'pub_arv_lannister', 'pub_arv_skywalker', 'pub_arv_targaryen', 'pub_arv_terra_cambara');

UPDATE pessoas SET tipo_tempo = 'ficticio' WHERE id IN (
    SELECT DISTINCT am.pessoa_id FROM arvore_membros am
    WHERE am.arvore_id IN ('pub_arv_buendia', 'pub_arv_compson', 'pub_arv_corleone', 'pub_arv_karamazov', 'pub_arv_lannister', 'pub_arv_skywalker', 'pub_arv_targaryen', 'pub_arv_terra_cambara')
    AND am.pessoa_id IS NOT NULL
);

